// ==UserScript==
// @name         MT98 Performance Optimizer
// @namespace    https://github.com/parhamghahremani
// @version      2.0.2
// @description  Performance and scrolling optimization for MT98
// @author       parham
// @match        https://mt98.ir/*
// @match        https://www.mt98.ir/*
// @run-at       document-start
// @grant        none
// @icon         data:image/svg+xml;base64,
// @downloadURL  https://raw.githubusercontent.com/parhamghahremani/mt98-performance-optimizer/main/dist/mt98-performance-optimizer.user.js
// @updateURL    https://raw.githubusercontent.com/parhamghahremani/mt98-performance-optimizer/main/dist/mt98-performance-optimizer.user.js
// @supportURL   https://github.com/parhamghahremani/mt98-performance-optimizer/issues
// @homepageURL  https://github.com/parhamghahremani/mt98-performance-optimizer
// @license      MIT
// ==/UserScript==

(function () {
    "use strict";

    /*
     * ================================================================
     * MT98 PERFORMANCE OPTIMIZER v2.0.2
     * ================================================================
     *
     * Designed primarily for Firefox Android.
     *
     * Main goals:
     *   1. Reduce paint/compositing cost.
     *   2. Reduce scroll-time visual effects.
     *   3. Reduce unnecessary image work.
     *   4. Improve very long MT98 pages.
     *   5. Avoid modifying Reader image quality.
     *
     * The script intentionally avoids aggressive DOM manipulation.
     *
     * Based on v2.0.0 - conservative, stable approach.
     * v2.0.1 adds incremental improvements based on research.
     * v2.0.2 adds custom icon and author metadata.
     */

    /* ---------------------------------------------------------------
     * Configuration
     * --------------------------------------------------------------- */

    const CONFIG = {
        // Enable image optimizations on normal pages.
        optimizeImages: true,

        // Enable content-visibility for large images.
        optimizeLargeImages: true,

        // Minimum rendered height for an image to receive
        // content-visibility optimization.
        largeImageHeight: 600,

        // Images farther than this amount below the viewport
        // may be converted to lazy-loading.
        lazyDistance: 1.5,

        // How long the temporary "scrolling" state remains active.
        scrollEndDelay: 120,

        // Delay for non-critical DOM optimization work.
        idleDelay: 300,

        // Maximum number of nodes processed during one idle pass.
        batchSize: 100,

        // NEW v2.0.1: Respect prefers-reduced-motion instead of killing all animations
        respectReducedMotion: true,

        // NEW v2.0.1: Protect above-fold images (first 2 viewports)
        protectAboveFold: true,
    };

    /* ---------------------------------------------------------------
     * Safety / page detection
     * --------------------------------------------------------------- */

    // Manual emergency disable:
    // Add ?mt98perf=off to the URL.
    if (new URLSearchParams(location.search).get("mt98perf") === "off") {
        return;
    }

    /*
     * Reader pages are handled more conservatively.
     *
     * The original problem appears to be on normal site pages rather
     * than the Reader itself, so we avoid aggressive image handling
     * there.
     */
    const isReader =
        /readerpage\.php/i.test(location.pathname) ||
        /\/reader(?:\/|$)/i.test(location.pathname);

    const shouldOptimizeImages =
        CONFIG.optimizeImages && !isReader;

    const shouldOptimizeLargeImages =
        CONFIG.optimizeLargeImages && !isReader;

    const shouldProtectAboveFold = CONFIG.protectAboveFold;

    /* ---------------------------------------------------------------
     * Early performance CSS
     * --------------------------------------------------------------- */

    const style = document.createElement("style");
    style.id = "mt98-performance-optimizer";

    // Build CSS dynamically based on config
    const css = `
        /*
         * ------------------------------------------------------------
         * Base optimization
         * ------------------------------------------------------------
         */

        html {
            scroll-behavior: auto !important;
            scroll-snap-type: none !important;
        }

        /*
         * FIX v2.0.1: Respect user's reduced-motion preference.
         * Disable animations/transitions ONLY for users who prefer reduced motion.
         * This avoids breaking normal site animations for users who don't need it.
         */
        @media (prefers-reduced-motion: reduce) {
            *,
            *::before,
            *::after {
                animation-duration: 0.01ms !important;
                animation-delay: 0s !important;
                animation-iteration-count: 1 !important;

                transition-duration: 0.01ms !important;
                transition-delay: 0s !important;
            }
        }

        html,
        body {
            scroll-snap-type: none !important;
        }

        /* Prevent unnecessary layer promotion */
        * {
            will-change: auto !important;
        }


        /*
         * ------------------------------------------------------------
         * Scroll-time optimization
         * ------------------------------------------------------------
         *
         * These properties are only enabled while the user is
         * physically scrolling.
         *
         * Shadows, text shadows and filters can be surprisingly
         * expensive on mobile GPUs when a large page is moving.
         */

        html.mt98-scrolling *,
        html.mt98-scrolling *::before,
        html.mt98-scrolling *::after {
            box-shadow: none !important;
            text-shadow: none !important;

            filter: none !important;
            -webkit-filter: none !important;

            backdrop-filter: none !important;
            -webkit-backdrop-filter: none !important;

            background-attachment: scroll !important;
        }


        /*
         * ------------------------------------------------------------
         * Image rendering
         * ------------------------------------------------------------
         */

        img {
            /*
             * Let Firefox perform image decoding asynchronously
             * where possible.
             */
            image-rendering: auto !important;
        }


        /*
         * ------------------------------------------------------------
         * Large-image optimization
         * ------------------------------------------------------------
         */

        img.mt98-large-image {
            content-visibility: auto !important;

            /*
             * This fallback is only used until Firefox remembers the
             * image's actual rendered size.
             */
            contain-intrinsic-size: auto 800px !important;
        }


        /*
         * ------------------------------------------------------------
         * Iframe optimization
         * ------------------------------------------------------------
         */

        iframe.mt98-lazy-frame {
            content-visibility: auto !important;
            contain-intrinsic-size: auto 300px !important;
        }
    `;

    style.textContent = css;

    /*
     * document.documentElement normally exists at document-start.
     * If not, wait until it becomes available.
     */
    if (document.documentElement) {
        document.documentElement.appendChild(style);
    } else {
        document.addEventListener(
            "DOMContentLoaded",
            () => document.documentElement.appendChild(style),
            { once: true }
        );
    }


    /* ---------------------------------------------------------------
     * Scrolling state
     * --------------------------------------------------------------- */

    let scrollTimer = 0;
    let scrollFrame = 0;

    function markScrolling() {
        if (scrollFrame) {
            return;
        }

        scrollFrame = requestAnimationFrame(() => {
            scrollFrame = 0;

            document.documentElement.classList.add(
                "mt98-scrolling"
            );

            clearTimeout(scrollTimer);

            scrollTimer = setTimeout(() => {
                document.documentElement.classList.remove(
                    "mt98-scrolling"
                );
            }, CONFIG.scrollEndDelay);
        });
    }

    /*
     * Passive listener:
     * this is important because the browser does not need to wait
     * for JavaScript before performing the scroll.
     */
    window.addEventListener(
        "scroll",
        markScrolling,
        { passive: true }
    );


    /* ---------------------------------------------------------------
     * Utility: schedule non-critical work
     * --------------------------------------------------------------- */

    function runWhenIdle(callback, timeout = CONFIG.idleDelay) {
        if ("requestIdleCallback" in window) {
            window.requestIdleCallback(callback, {
                timeout
            });
        } else {
            setTimeout(callback, timeout);
        }
    }


    /* ---------------------------------------------------------------
     * Image optimization
     * --------------------------------------------------------------- */

    const processedImages = new WeakSet();

    function optimizeImage(img) {
        if (!(img instanceof HTMLImageElement)) {
            return;
        }

        if (processedImages.has(img)) {
            return;
        }

        processedImages.add(img);

        /*
         * Firefox can decode the image asynchronously.
         */
        try {
            img.decoding = "async";
        } catch {
            // Ignore unsupported implementations.
        }

        /*
         * We only use lazy loading for images which are clearly
         * below the initial viewport.
         *
         * This prevents important above-the-fold images from being
         * unnecessarily delayed.
         *
         * FIX v2.0.1: Protect first 2 viewports completely
         */
        if (shouldOptimizeImages) {
            try {
                const rect = img.getBoundingClientRect();

                const viewportHeight =
                    window.innerHeight ||
                    document.documentElement.clientHeight ||
                    800;

                // FIX v2.0.1: Protect first 2 viewports - no lazy loading
                if (shouldProtectAboveFold && rect.top <= viewportHeight * 2) {
                    // First 2 viewports: eager loading, high priority
                    img.loading = "eager";
                    if ("fetchPriority" in img) {
                        img.fetchPriority = "high";
                    }
                } else if (rect.top > viewportHeight * CONFIG.lazyDistance) {
                    // Beyond lazyDistance: lazy loading, low priority
                    img.loading = "lazy";

                    if ("fetchPriority" in img) {
                        img.fetchPriority = "low";
                    }
                } else {
                    // Middle zone: eager but normal priority
                    img.loading = "eager";
                    if ("fetchPriority" in img) {
                        img.fetchPriority = "auto";
                    }
                }
            } catch {
                // Ignore geometry errors.
            }
        }

        /*
         * Large images get content-visibility after they are loaded,
         * because we then know their actual rendered dimensions.
         */
        if (shouldOptimizeLargeImages) {
            if (img.complete) {
                optimizeLoadedImage(img);
            } else {
                img.addEventListener(
                    "load",
                    () => optimizeLoadedImage(img),
                    {
                        once: true,
                        passive: true
                    }
                );
            }
        }
    }


    function optimizeLoadedImage(img) {
        if (!(img instanceof HTMLImageElement)) {
            return;
        }

        if (!img.naturalWidth || !img.naturalHeight) {
            return;
        }

        try {
            const rect = img.getBoundingClientRect();
            const renderedHeight = rect.height;

            if (
                renderedHeight >=
                CONFIG.largeImageHeight
            ) {
                img.classList.add(
                    "mt98-large-image"
                );

                /*
                 * Remember the actual rendered size.
                 *
                 * This greatly reduces the possibility of layout
                 * shifts when Firefox skips an off-screen image.
                 */
                if (renderedHeight > 0) {
                    img.style.setProperty(
                        "contain-intrinsic-size",
                        `auto ${Math.ceil(renderedHeight)}px`,
                        "important"
                    );
                }
            }
        } catch {
            // Ignore geometry errors.
        }
    }


    /* ---------------------------------------------------------------
     * Iframe optimization
     * --------------------------------------------------------------- */

    const processedFrames = new WeakSet();

    function optimizeIframe(frame) {
        if (!(frame instanceof HTMLIFrameElement)) {
            return;
        }

        if (processedFrames.has(frame)) {
            return;
        }

        processedFrames.add(frame);

        /*
         * Do not interfere with visible frames.
         * Only defer clearly off-screen frames.
         */
        try {
            const rect = frame.getBoundingClientRect();

            const viewportHeight =
                window.innerHeight ||
                document.documentElement.clientHeight ||
                800;

            if (
                rect.top >
                viewportHeight * CONFIG.lazyDistance
            ) {
                frame.loading = "lazy";
                frame.classList.add(
                    "mt98-lazy-frame"
                );
            }
        } catch {
            // Ignore geometry errors.
        }
    }


    /* ---------------------------------------------------------------
     * Batch DOM processing
     * --------------------------------------------------------------- */

    const imageQueue = [];
    const frameQueue = [];
    let processing = false;

    function queueCurrentContent() {
        if (!shouldOptimizeImages &&
            !shouldOptimizeLargeImages) {
            return;
        }

        const images =
            document.querySelectorAll("img");

        const frames =
            document.querySelectorAll("iframe");

        for (const img of images) {
            if (!processedImages.has(img)) {
                imageQueue.push(img);
            }
        }

        for (const frame of frames) {
            if (!processedFrames.has(frame)) {
                frameQueue.push(frame);
            }
        }

        processQueues();
    }


    function processQueues() {
        if (processing) {
            return;
        }

        processing = true;

        runWhenIdle(() => {
            let processed = 0;

            while (
                imageQueue.length &&
                processed < CONFIG.batchSize
            ) {
                optimizeImage(
                    imageQueue.shift()
                );

                processed++;
            }

            while (
                frameQueue.length &&
                processed < CONFIG.batchSize
            ) {
                optimizeIframe(
                    frameQueue.shift()
                );

                processed++;
            }

            processing = false;

            /*
             * Continue later rather than processing hundreds of
             * elements in one blocking task.
             */
            if (
                imageQueue.length ||
                frameQueue.length
            ) {
                processQueues();
            }
        });
    }


    /* ---------------------------------------------------------------
     * MutationObserver
     * --------------------------------------------------------------- */

    let mutationScheduled = false;

    const observer =
        new MutationObserver((mutations) => {
            let foundRelevantNode = false;

            for (const mutation of mutations) {
                if (!mutation.addedNodes.length) {
                    continue;
                }

                for (const node of mutation.addedNodes) {
                    if (
                        node.nodeType !== Node.ELEMENT_NODE
                    ) {
                        continue;
                    }

                    /*
                     * Do not walk the entire subtree immediately.
                     * Just collect relevant elements.
                     */
                    const element = node;

                    if (
                        element.matches &&
                        element.matches("img")
                    ) {
                        if (!processedImages.has(element)) {
                            imageQueue.push(element);
                            foundRelevantNode = true;
                        }
                    }

                    if (
                        element.matches &&
                        element.matches("iframe")
                    ) {
                        if (!processedFrames.has(element)) {
                            frameQueue.push(element);
                            foundRelevantNode = true;
                        }
                    }

                    if (
                        element.querySelectorAll
                    ) {
                        const imgs =
                            element.querySelectorAll("img");

                        const frames =
                            element.querySelectorAll("iframe");

                        for (const img of imgs) {
                            if (!processedImages.has(img)) {
                                imageQueue.push(img);
                                foundRelevantNode = true;
                            }
                        }

                        for (const frame of frames) {
                            if (!processedFrames.has(frame)) {
                                frameQueue.push(frame);
                                foundRelevantNode = true;
                            }
                        }
                    }
                }
            }

            if (
                foundRelevantNode &&
                !mutationScheduled
            ) {
                mutationScheduled = true;

                runWhenIdle(() => {
                    mutationScheduled = false;
                    processQueues();
                });
            }
        });


    /* ---------------------------------------------------------------
     * Start observing after the document becomes available
     * --------------------------------------------------------------- */

    function startObserver() {
        if (!document.body) {
            return;
        }

        observer.observe(document.body, {
            childList: true,
            subtree: true
        });

        queueCurrentContent();
    }


    if (document.readyState === "loading") {
        document.addEventListener(
            "DOMContentLoaded",
            startObserver,
            { once: true }
        );
    } else {
        startObserver();
    }


    /* ---------------------------------------------------------------
     * Re-process after full page load
     * --------------------------------------------------------------- */

    window.addEventListener(
        "load",
        () => {
            runWhenIdle(() => {
                queueCurrentContent();
            }, 500);
        },
        {
            once: true,
            passive: true
        }
    );


    /* ---------------------------------------------------------------
     * Handle orientation / viewport changes
     * --------------------------------------------------------------- */

    let resizeTimer = 0;

    window.addEventListener(
        "resize",
        () => {
            clearTimeout(resizeTimer);

            resizeTimer = setTimeout(() => {
                queueCurrentContent();
            }, 250);
        },
        {
            passive: true
        }
    );


    /* ---------------------------------------------------------------
     * Cleanup when page is being unloaded
     * --------------------------------------------------------------- */

    window.addEventListener(
        "pagehide",
        () => {
            clearTimeout(scrollTimer);

            if (scrollFrame) {
                cancelAnimationFrame(scrollFrame);
            }

            observer.disconnect();
        },
        {
            once: true,
            passive: true
        }
    );

})();